ruleToc.nextTocUrl:
@js:
if(/<a href=".*?\/works">Works \(\d+\)<\/a>|\d+ - \d+ of \d+ Works by/.test(result)){
	   java.log(1)
    var match1 = String(java.getString('@css:ul[role="navigation"] a[href$=/works]@text')).match(/(\d+)/);
    var match2 = result.match(/\d+ - \d+ of (\d+) Works by/);
    var num = match1 && match1[1] !== undefined ? match1[1] : (match2 && match2[1] !== undefined ? match2[1] : undefined);
    num = num !== undefined && num !== null ? num : 0;
    var page = Math.ceil(Number(num)/20);
    var list = [];
    if(page>=2 && !/page=(?:1|2)$/.test(baseUrl)){
        for(var i=1;i<=page;i++){
            list.push(baseUrl.replace(/\/works.*/,'')+"/works?page="+i);
        }
        result = list;
    }else if(page === 1){
        java.log(2);
        result = baseUrl.replace(/\/works.*/,'')+"/works?page="+page;
    }
}

